tool_schemas.implementation:
def todoist_create_task(account_id, idempotency_key=None, content=None, description=None, project_id=None, priority=None, due_date=None, due_at=None, labels=None, assignee_todoist_user_id=None, order_index=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_invocation(tool_name, acct_id, request_payload, status, error_message=None, response_payload=None, matched_task_id=None, resolved_search_name=None, idempotency_key_val=None, duration_ms=None):
        inv = _load("tool_invocations.json")
        def _new_id(prefix="tdst_inv_"):
            # deterministic enough for local store
            return prefix + uuid.uuid4().hex.upper()
        row = {
            "id": _new_id(),
            "account_id": acct_id,
            "tool_name": tool_name,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "resolved_search_name": resolved_search_name,
            "matched_task_id": matched_task_id,
            "status": status,
            "error_message": error_message,
            "response_payload": response_payload,
            "idempotency_key": idempotency_key_val,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        inv.append(row)
        _save("tool_invocations.json", inv)
        return row

    def _acct_active(acct_id, accounts):
        for a in accounts:
            if a.get("id") == acct_id:
                return a if a.get("status") == "active" and a.get("provider") == "todoist" else None
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "INVALID"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                # treat naive as UTC
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "INVALID"

    def _normalize_content(s):
        return " ".join(s.strip().split()).lower()

    def _make_ulid_like(prefix):
        # Not a true ULID; only needs to satisfy pattern ^tdst_xxx_[0-9A-Z]{10,}$
        return prefix + uuid.uuid4().hex.upper()

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^tdst_acct_[0-9A-Z]{10,}$", account_id):
        # log invocation even on validation error; account_id is required but may be invalid; best-effort
        _record_invocation("todoist_create_task", account_id if isinstance(account_id, str) else "unknown", {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "description": description,
            "project_id": project_id, "priority": priority, "due_date": due_date, "due_at": due_at,
            "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id, "order_index": order_index
        }, "failed", error_message="Invalid account_id")
        return _err("VALIDATION_ERROR", "Invalid account_id")
    if not isinstance(content, str) or not content.strip():
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "description": description,
            "project_id": project_id, "priority": priority, "due_date": due_date, "due_at": due_at,
            "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id, "order_index": order_index
        }, "failed", error_message="content is required")
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content
        }, "failed", error_message="Invalid idempotency_key")
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if description is not None and not isinstance(description, str):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "description": description
        }, "failed", error_message="Invalid description")
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{10,}$", project_id)):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "project_id": project_id
        }, "failed", error_message="Invalid project_id")
        return _err("VALIDATION_ERROR", "Invalid project_id")
    if priority is not None:
        if not isinstance(priority, int) or priority < 1 or priority > 4:
            _record_invocation("todoist_create_task", account_id, {
                "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "priority": priority
            }, "failed", error_message="Invalid priority")
            return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4")
    if due_date is not None and (not isinstance(due_date, str) or not due_date.strip()):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "due_date": due_date
        }, "failed", error_message="Invalid due_date")
        return _err("VALIDATION_ERROR", "due_date must be a non-empty string when provided")
    due_at_dt = None
    if due_at is not None:
        due_at_dt = _parse_rfc3339(due_at)
        if due_at_dt == "INVALID":
            _record_invocation("todoist_create_task", account_id, {
                "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "due_at": due_at
            }, "failed", error_message="Invalid due_at")
            return _err("VALIDATION_ERROR", "due_at must be a valid RFC3339 timestamp")
    if labels is None:
        labels = []
    if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "labels": labels
        }, "failed", error_message="Invalid labels")
        return _err("VALIDATION_ERROR", "labels must be an array of strings")
    if assignee_todoist_user_id is not None and not isinstance(assignee_todoist_user_id, str):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "assignee_todoist_user_id": assignee_todoist_user_id
        }, "failed", error_message="Invalid assignee_todoist_user_id")
        return _err("VALIDATION_ERROR", "assignee_todoist_user_id must be a string when provided")
    if order_index is not None and not isinstance(order_index, int):
        _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "order_index": order_index
        }, "failed", error_message="Invalid order_index")
        return _err("VALIDATION_ERROR", "order_index must be an integer when provided")

    # Enforce "due_at and due_date may not both be set unless vendor payload includes both"
    # In this local server, requests are the vendor payload; allow both if both explicitly provided, else normalize to one.
    if due_at is not None and due_date is not None:
        # both provided explicitly => accept
        pass
    else:
        # normalize: if due_at provided, clear due_date; if due_date provided, clear due_at string
        if due_at is not None and due_date is None:
            pass
        if due_date is not None and due_at is None:
            pass

    accounts = _load("accounts.json")
    acct = _acct_active(account_id, accounts)
    if not acct:
        inv = _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "description": description,
            "project_id": project_id, "priority": priority, "due_date": due_date, "due_at": due_at,
            "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id, "order_index": order_index
        }, "failed", error_message="No active Todoist account found")
        inv["duration_ms"] = int((time.time() - t0) * 1000)
        inv["updated_at"] = now
        tool_inv = _load("tool_invocations.json")
        for i in range(len(tool_inv)-1, -1, -1):
            if tool_inv[i].get("id") == inv["id"]:
                tool_inv[i] = inv
                break
        _save("tool_invocations.json", tool_inv)
        return _err("UNAUTHORIZED", "No active Todoist account configured for this account_id")

    # Idempotency: unique(account_id, idempotency_key)
    if idempotency_key is not None:
        invs = _load("tool_invocations.json")
        for r in invs:
            if r.get("account_id") == account_id and r.get("idempotency_key") == idempotency_key and r.get("tool_name") == "todoist_create_task" and r.get("status") == "succeeded":
                matched_task_id = r.get("matched_task_id")
                if matched_task_id:
                    tasks = _load("tasks.json")
                    for t in tasks:
                        if t.get("id") == matched_task_id and t.get("account_id") == account_id:
                            # log this call too (observable dynamics)
                            inv = _record_invocation("todoist_create_task", account_id, {
                                "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "description": description,
                                "project_id": project_id, "priority": priority, "due_date": due_date, "due_at": due_at,
                                "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id, "order_index": order_index
                            }, "succeeded", response_payload={"idempotent_replay": True, "task_id": matched_task_id}, matched_task_id=matched_task_id, idempotency_key_val=idempotency_key, duration_ms=int((time.time()-t0)*1000))
                            return {"task": t, "idempotent": True, "invocation_id": inv.get("id")}

    # Validate project existence if provided
    projects = _load("projects.json")
    if project_id is not None:
        prj_ok = False
        for p in projects:
            if p.get("id") == project_id and p.get("account_id") == account_id and p.get("status") == "active":
                prj_ok = True
                break
        if not prj_ok:
            inv = _record_invocation("todoist_create_task", account_id, {
                "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "project_id": project_id
            }, "failed", error_message="Project not found for account")
            inv["duration_ms"] = int((time.time() - t0) * 1000)
            inv["updated_at"] = now
            tool_inv = _load("tool_invocations.json")
            for i in range(len(tool_inv)-1, -1, -1):
                if tool_inv[i].get("id") == inv["id"]:
                    tool_inv[i] = inv
                    break
            _save("tool_invocations.json", tool_inv)
            return _err("NOT_FOUND", "project_id not found for this account")

    # Simulate vendor create: generate stable todoist_task_id
    vendor_task_id = "vnd_tsk_" + uuid.uuid4().hex  # not exposed pattern in schema; ok as string
    content_norm = _normalize_content(content)

    tasks = _load("tasks.json")

    # Upsert by unique(account_id, todoist_task_id) - should be new
    existing = None
    for t in tasks:
        if t.get("account_id") == account_id and t.get("todoist_task_id") == vendor_task_id:
            existing = t
            break

    if existing:
        # Extremely unlikely; treat as conflict
        inv = _record_invocation("todoist_create_task", account_id, {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content
        }, "failed", error_message="Vendor task id collision", idempotency_key_val=idempotency_key)
        inv["duration_ms"] = int((time.time() - t0) * 1000)
        inv["updated_at"] = now
        tool_inv = _load("tool_invocations.json")
        for i in range(len(tool_inv)-1, -1, -1):
            if tool_inv[i].get("id") == inv["id"]:
                tool_inv[i] = inv
                break
        _save("tool_invocations.json", tool_inv)
        return _err("CONFLICT", "Task already exists with the generated vendor id (collision)")

    task_id = _make_ulid_like("tdst_tsk_")
    new_task = {
        "id": task_id,
        "account_id": account_id,
        "todoist_task_id": vendor_task_id,
        "project_id": project_id,
        "content": content.strip(),
        "content_normalized": content_norm,
        "description": description,
        "priority": priority,
        "due_at": (due_at_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None).isoformat() + "Z") if isinstance(due_at_dt, datetime.datetime) else (due_at if isinstance(due_at, str) else None),
        "due_date": due_date,
        "labels": labels,
        "assignee_todoist_user_id": assignee_todoist_user_id,
        "order_index": order_index,
        "status": "active",
        "completed_at": None,
        "deleted_at": None,
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now
    }
    tasks.append(new_task)
    _save("tasks.json", tasks)

    # Ensure exactly one full-term index row for this task
    idx = _load("task_search_index.json")
    # Remove any existing full rows for this (shouldn't exist)
    idx = [r for r in idx if not (r.get("account_id") == account_id and r.get("task_id") == task_id and r.get("term_type") == "full")]
    idx_id = _make_ulid_like("tdst_idx_")
    idx.append({
        "id": idx_id,
        "account_id": account_id,
        "task_id": task_id,
        "term": content_norm,
        "term_type": "full",
        "created_at": now,
        "updated_at": now
    })
    _save("task_search_index.json", idx)

    # Update account last_verified_at (success calling vendor)
    acct["last_verified_at"] = now
    acct["updated_at"] = now
    for i, a in enumerate(accounts):
        if a.get("id") == account_id:
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    inv = _record_invocation(
        "todoist_create_task",
        account_id,
        {
            "account_id": account_id, "idempotency_key": idempotency_key, "content": content, "description": description,
            "project_id": project_id, "priority": priority, "due_date": due_date, "due_at": due_at,
            "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id, "order_index": order_index
        },
        "succeeded",
        response_payload={"task_id": task_id},
        matched_task_id=task_id,
        idempotency_key_val=idempotency_key,
        duration_ms=int((time.time() - t0) * 1000)
    )
    return {"task": new_task, "invocation_id": inv.get("id")}

def todoist_get_tasks(account_id, status=None, project_id=None, content_query=None, labels=None, assignee_todoist_user_id=None, due_before=None, due_after=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_invocation(tool_name, acct_id, request_payload, status_s, error_message=None, response_payload=None, matched_task_id=None, resolved_search_name=None, idempotency_key_val=None, duration_ms=None):
        inv = _load("tool_invocations.json")
        def _new_id(prefix="tdst_inv_"):
            return prefix + uuid.uuid4().hex.upper()
        row = {
            "id": _new_id(),
            "account_id": acct_id,
            "tool_name": tool_name,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "resolved_search_name": resolved_search_name,
            "matched_task_id": matched_task_id,
            "status": status_s,
            "error_message": error_message,
            "response_payload": response_payload,
            "idempotency_key": idempotency_key_val,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        inv.append(row)
        _save("tool_invocations.json", inv)
        return row

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "INVALID"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "INVALID"

    def _norm(s):
        return " ".join(s.strip().split()).lower()

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^tdst_acct_[0-9A-Z]{10,}$", account_id):
        _record_invocation("todoist_get_tasks", account_id if isinstance(account_id, str) else "unknown", {"account_id": account_id}, "failed", error_message="Invalid account_id")
        return _err("VALIDATION_ERROR", "Invalid account_id")
    if status is not None and status not in ("active", "completed", "deleted"):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "status": status}, "failed", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "status must be one of: active, completed, deleted")
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{10,}$", project_id)):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "project_id": project_id}, "failed", error_message="Invalid project_id")
        return _err("VALIDATION_ERROR", "Invalid project_id")
    if content_query is not None and not isinstance(content_query, str):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "content_query": content_query}, "failed", error_message="Invalid content_query")
        return _err("VALIDATION_ERROR", "content_query must be a string when provided")
    if labels is None:
        labels = None
    if labels is not None and (not isinstance(labels, list) or any(not isinstance(x, str) for x in labels)):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "labels": labels}, "failed", error_message="Invalid labels")
        return _err("VALIDATION_ERROR", "labels must be an array of strings when provided")
    if assignee_todoist_user_id is not None and not isinstance(assignee_todoist_user_id, str):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "assignee_todoist_user_id": assignee_todoist_user_id}, "failed", error_message="Invalid assignee")
        return _err("VALIDATION_ERROR", "assignee_todoist_user_id must be a string when provided")
    due_before_dt = _parse_rfc3339(due_before)
    if due_before_dt == "INVALID":
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "due_before": due_before}, "failed", error_message="Invalid due_before")
        return _err("VALIDATION_ERROR", "due_before must be RFC3339 date-time when provided")
    due_after_dt = _parse_rfc3339(due_after)
    if due_after_dt == "INVALID":
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "due_after": due_after}, "failed", error_message="Invalid due_after")
        return _err("VALIDATION_ERROR", "due_after must be RFC3339 date-time when provided")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "limit": limit}, "failed", error_message="Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "cursor": cursor}, "failed", error_message="Invalid cursor")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")
    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at", "due_at", "priority", "order_index"):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "sort_by": sort_by}, "failed", error_message="Invalid sort_by")
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, due_at, priority, order_index")
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "sort_order": sort_order}, "failed", error_message="Invalid sort_order")
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    # Account authorization
    accounts = _load("accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id and a.get("provider") == "todoist" and a.get("status") == "active":
            acct = a
            break
    if not acct:
        inv = _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id}, "failed", error_message="No active Todoist account found", duration_ms=int((time.time()-t0)*1000))
        return _err("UNAUTHORIZED", "No active Todoist account configured for this account_id")

    # Refresh if stale (implementation-defined): if any task last_synced_at older than 5 minutes, "refresh" by bumping
    tasks = _load("tasks.json")
    stale_cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(minutes=5)
    refreshed_any = False
    for i, t in enumerate(tasks):
        if t.get("account_id") != account_id:
            continue
        lsa = t.get("last_synced_at")
        dt = None
        if isinstance(lsa, str) and lsa.endswith("Z"):
            try:
                dt = datetime.datetime.fromisoformat(lsa[:-1] + "+00:00")
            except ValueError:
                dt = None
        if dt is None or dt < stale_cutoff:
            tasks[i]["last_synced_at"] = now
            tasks[i]["updated_at"] = tasks[i].get("updated_at") or now
            refreshed_any = True
    if refreshed_any:
        _save("tasks.json", tasks)
        acct["last_verified_at"] = now
        acct["updated_at"] = now
        for i, a in enumerate(accounts):
            if a.get("id") == account_id:
                accounts[i] = acct
                break
        _save("accounts.json", accounts)

    # Apply filters
    rows = [t for t in tasks if t.get("account_id") == account_id]

    if status is not None:
        rows = [t for t in rows if t.get("status") == status]
    if project_id is not None:
        rows = [t for t in rows if t.get("project_id") == project_id]
    if assignee_todoist_user_id is not None:
        rows = [t for t in rows if t.get("assignee_todoist_user_id") == assignee_todoist_user_id]
    if labels is not None:
        want = set(labels)
        def _has_all(t):
            lab = t.get("labels") or []
            return want.issubset(set(lab))
        rows = [t for t in rows if _has_all(t)]
    if content_query is not None and content_query.strip():
        q = _norm(content_query)
        rows = [t for t in rows if q in (t.get("content_normalized") or _norm(t.get("content") or ""))]

    def _task_due_at_dt(t):
        da = t.get("due_at")
        if not isinstance(da, str):
            return None
        p = _parse_rfc3339(da)
        return None if p == "INVALID" else p

    if due_before_dt is not None:
        rows = [t for t in rows if (_task_due_at_dt(t) is not None and _task_due_at_dt(t) < due_before_dt)]
    if due_after_dt is not None:
        rows = [t for t in rows if (_task_due_at_dt(t) is not None and _task_due_at_dt(t) > due_after_dt)]

    # Sort
    def _sort_key(t):
        v = t.get(sort_by)
        if sort_by in ("created_at", "updated_at", "due_at"):
            if isinstance(v, str):
                dt = _parse_rfc3339(v)
                if dt == "INVALID" or dt is None:
                    return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                return dt
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort_by in ("priority", "order_index"):
            if v is None:
                return -10**9
            return v if isinstance(v, int) else -10**9
        return v

    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor paging: cursor is base64("offset:<n>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    raise ValueError
            else:
                raise ValueError
        except Exception:
            inv = _record_invocation("todoist_get_tasks", account_id, {"account_id": account_id, "cursor": cursor}, "failed", error_message="Invalid cursor", duration_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    inv = _record_invocation(
        "todoist_get_tasks",
        account_id,
        {
            "account_id": account_id, "status": status, "project_id": project_id, "content_query": content_query,
            "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id, "due_before": due_before,
            "due_after": due_after, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order
        },
        "succeeded",
        response_payload={"returned": len(page), "total": total, "has_more": has_more},
        duration_ms=int((time.time() - t0) * 1000)
    )
    return {
        "tasks": page,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
        "invocation_id": inv.get("id")
    }

def todoist_update_task(account_id, idempotency_key=None, search_name=None, task_id=None, content=None, description=None, project_id=None, priority=None, due_date=None, due_at=None, labels=None, assignee_todoist_user_id=None, order_index=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_invocation(tool_name, acct_id, request_payload, status_s, error_message=None, response_payload=None, matched_task_id=None, resolved_search_name=None, idempotency_key_val=None, duration_ms=None):
        inv = _load("tool_invocations.json")
        def _new_id(prefix="tdst_inv_"):
            return prefix + uuid.uuid4().hex.upper()
        row = {
            "id": _new_id(),
            "account_id": acct_id,
            "tool_name": tool_name,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "resolved_search_name": resolved_search_name,
            "matched_task_id": matched_task_id,
            "status": status_s,
            "error_message": error_message,
            "response_payload": response_payload,
            "idempotency_key": idempotency_key_val,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        inv.append(row)
        _save("tool_invocations.json", inv)
        return row

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "INVALID"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "INVALID"

    def _norm(s):
        return " ".join(s.strip().split()).lower()

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^tdst_acct_[0-9A-Z]{10,}$", account_id):
        _record_invocation("todoist_update_task", account_id if isinstance(account_id, str) else "unknown", {"account_id": account_id}, "failed", error_message="Invalid account_id")
        return _err("VALIDATION_ERROR", "Invalid account_id")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "idempotency_key": idempotency_key}, "failed", error_message="Invalid idempotency_key")
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if task_id is not None and (not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{10,}$", task_id)):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "task_id": task_id}, "failed", error_message="Invalid task_id")
        return _err("VALIDATION_ERROR", "Invalid task_id")
    if task_id is None and (search_name is None or not isinstance(search_name, str) or not search_name.strip()):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "search_name": search_name}, "failed", error_message="Missing identifier")
        return _err("VALIDATION_ERROR", "Either task_id or search_name must be provided")
    if content is not None and (not isinstance(content, str) or not content.strip()):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "content": content}, "failed", error_message="Invalid content")
        return _err("VALIDATION_ERROR", "content must be a non-empty string when provided")
    if description is not None and not isinstance(description, str):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "description": description}, "failed", error_message="Invalid description")
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{10,}$", project_id)):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "project_id": project_id}, "failed", error_message="Invalid project_id")
        return _err("VALIDATION_ERROR", "Invalid project_id")
    if priority is not None and (not isinstance(priority, int) or priority < 1 or priority > 4):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "priority": priority}, "failed", error_message="Invalid priority")
        return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4")
    due_at_dt = _parse_rfc3339(due_at)
    if due_at_dt == "INVALID":
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "due_at": due_at}, "failed", error_message="Invalid due_at")
        return _err("VALIDATION_ERROR", "due_at must be RFC3339 date-time when provided")
    if due_date is not None and (not isinstance(due_date, str) or not due_date.strip()):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "due_date": due_date}, "failed", error_message="Invalid due_date")
        return _err("VALIDATION_ERROR", "due_date must be a non-empty string when provided")
    if labels is not None and (not isinstance(labels, list) or any(not isinstance(x, str) for x in labels)):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "labels": labels}, "failed", error_message="Invalid labels")
        return _err("VALIDATION_ERROR", "labels must be an array of strings when provided")
    if assignee_todoist_user_id is not None and not isinstance(assignee_todoist_user_id, str):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "assignee_todoist_user_id": assignee_todoist_user_id}, "failed", error_message="Invalid assignee")
        return _err("VALIDATION_ERROR", "assignee_todoist_user_id must be a string when provided")
    if order_index is not None and not isinstance(order_index, int):
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "order_index": order_index}, "failed", error_message="Invalid order_index")
        return _err("VALIDATION_ERROR", "order_index must be an integer when provided")

    accounts = _load("accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id and a.get("provider") == "todoist" and a.get("status") == "active":
            acct = a
            break
    if not acct:
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id}, "failed", error_message="No active Todoist account found", duration_ms=int((time.time()-t0)*1000))
        return _err("UNAUTHORIZED", "No active Todoist account configured for this account_id")

    # Idempotency replay
    if idempotency_key is not None:
        invs = _load("tool_invocations.json")
        for r in invs:
            if r.get("account_id") == account_id and r.get("idempotency_key") == idempotency_key and r.get("tool_name") == "todoist_update_task" and r.get("status") == "succeeded":
                matched_task_id = r.get("matched_task_id")
                if matched_task_id:
                    tasks = _load("tasks.json")
                    for t in tasks:
                        if t.get("id") == matched_task_id and t.get("account_id") == account_id:
                            inv = _record_invocation("todoist_update_task", account_id, {
                                "account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name,
                                "task_id": task_id, "content": content, "description": description, "project_id": project_id,
                                "priority": priority, "due_date": due_date, "due_at": due_at, "labels": labels,
                                "assignee_todoist_user_id": assignee_todoist_user_id, "order_index": order_index
                            }, "succeeded", response_payload={"idempotent_replay": True, "task_id": matched_task_id}, matched_task_id=matched_task_id, resolved_search_name=_norm(search_name) if isinstance(search_name, str) else None, idempotency_key_val=idempotency_key, duration_ms=int((time.time()-t0)*1000))
                            return {"task": t, "idempotent": True, "invocation_id": inv.get("id")}

    tasks = _load("tasks.json")
    idx = _load("task_search_index.json")
    projects = _load("projects.json")

    # Validate target project if provided
    if project_id is not None:
        ok = any(p.get("id") == project_id and p.get("account_id") == account_id and p.get("status") == "active" for p in projects)
        if not ok:
            _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "project_id": project_id}, "failed", error_message="Project not found", duration_ms=int((time.time()-t0)*1000))
            return _err("NOT_FOUND", "project_id not found for this account")

    resolved_search = _norm(search_name) if isinstance(search_name, str) else None

    # Resolve task
    target = None
    if task_id is not None:
        for t in tasks:
            if t.get("id") == task_id and t.get("account_id") == account_id:
                target = t
                break
        if not target:
            _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "task_id": task_id}, "failed", error_message="Task not found", duration_ms=int((time.time()-t0)*1000))
            return _err("NOT_FOUND", "Task not found")
    else:
        # search by content_normalized and/or task_search_index.term
        candidates = []
        if resolved_search:
            for t in tasks:
                if t.get("account_id") != account_id:
                    continue
                if t.get("status") != "active":
                    continue
                if (t.get("content_normalized") or "") == resolved_search:
                    candidates.append(t)
            if not candidates:
                # try index
                task_ids = set()
                for r in idx:
                    if r.get("account_id") == account_id and r.get("term") == resolved_search:
                        task_ids.add(r.get("task_id"))
                if task_ids:
                    for t in tasks:
                        if t.get("account_id") == account_id and t.get("status") == "active" and t.get("id") in task_ids:
                            candidates.append(t)
        if not candidates:
            _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "search_name": search_name}, "failed", error_message="No matching task", resolved_search_name=resolved_search, duration_ms=int((time.time()-t0)*1000))
            return _err("NOT_FOUND", "No active task matched search_name")
        # deterministic tie-breaker: most recently updated active task
        def _upd(t):
            return t.get("updated_at") or t.get("created_at") or ""
        candidates.sort(key=_upd, reverse=True)
        if len(candidates) > 1:
            # tie-breaker applied deterministically; proceed with top one
            target = candidates[0]
        else:
            target = candidates[0]

    if target.get("status") == "deleted":
        _record_invocation("todoist_update_task", account_id, {"account_id": account_id, "task_id": target.get("id")}, "failed", error_message="Cannot update deleted task", matched_task_id=target.get("id"), resolved_search_name=resolved_search, duration_ms=int((time.time()-t0)*1000))
        return _err("INVALID_TRANSITION", "Cannot update a deleted task")

    # Apply updates (simulate vendor update success)
    changed = False
    if content is not None:
        new_c = content.strip()
        if new_c != target.get("content"):
            target["content"] = new_c
            target["content_normalized"] = _norm(new_c)
            changed = True
    if description is not None:
        if description != target.get("description"):
            target["description"] = description
            changed = True
    if project_id is not None:
        if project_id != target.get("project_id"):
            target["project_id"] = project_id
            changed = True
    if priority is not None:
        if priority != target.get("priority"):
            target["priority"] = priority
            changed = True
    if due_at is not None or due_date is not None:
        # set whichever provided; allow both if both provided
        if due_at is not None:
            target["due_at"] = (due_at_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None).isoformat() + "Z") if isinstance(due_at_dt, datetime.datetime) else due_at
            changed = True
        if due_date is not None:
            target["due_date"] = due_date
            changed = True
        # If only one provided, do not auto-clear the other (vendor may keep both); but normalize if explicitly clearing not supported.
    if labels is not None:
        target["labels"] = labels
        changed = True
    if assignee_todoist_user_id is not None:
        target["assignee_todoist_user_id"] = assignee_todoist_user_id
        changed = True
    if order_index is not None:
        target["order_index"] = order_index
        changed = True

    if not changed:
        # Still record succeeded (real APIs often allow no-op update). But must have effect? Here it matched a row; effect is audit timestamps.
        pass

    target["updated_at"] = now
    target["last_synced_at"] = now

    # Persist tasks
    for i, t in enumerate(tasks):
        if t.get("id") == target.get("id") and t.get("account_id") == account_id:
            tasks[i] = target
            break
    _save("tasks.json", tasks)

    # Ensure exactly one full-term index for this task
    idx = [r for r in idx if not (r.get("account_id") == account_id and r.get("task_id") == target.get("id") and r.get("term_type") == "full")]
    idx.append({
        "id": "tdst_idx_" + uuid.uuid4().hex.upper(),
        "account_id": account_id,
        "task_id": target.get("id"),
        "term": target.get("content_normalized") or _norm(target.get("content") or ""),
        "term_type": "full",
        "created_at": now,
        "updated_at": now
    })
    _save("task_search_index.json", idx)

    # Update account verification
    acct["last_verified_at"] = now
    acct["updated_at"] = now
    for i, a in enumerate(accounts):
        if a.get("id") == account_id:
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    inv = _record_invocation(
        "todoist_update_task",
        account_id,
        {
            "account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id,
            "content": content, "description": description, "project_id": project_id, "priority": priority,
            "due_date": due_date, "due_at": due_at, "labels": labels, "assignee_todoist_user_id": assignee_todoist_user_id,
            "order_index": order_index
        },
        "succeeded",
        response_payload={"task_id": target.get("id")},
        matched_task_id=target.get("id"),
        resolved_search_name=resolved_search,
        idempotency_key_val=idempotency_key,
        duration_ms=int((time.time() - t0) * 1000)
    )
    return {"task": target, "invocation_id": inv.get("id")}

