                # log this call too
                inv = _record_invocation("todoist_delete_task", account_id, {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id}, "succeeded", response_payload={"idempotent_replay": True}, matched_task_id=r.get("matched_task_id"), resolved_search_name=_norm(search_name) if isinstance(search_name, str) else None, idempotency_key_val=idempotency_key, duration_ms=int((time.time()-t0)*1000))
