                break
        if not target:
            _record_invocation("todoist_delete_task", account_id, {"account_id": account_id, "task_id": task_id}, "failed", error_message="Task not found", duration_ms=int((time.time()-t0)*1000))
            return _err("NOT_FOUND", "Task not found")
    else:
        candidates = []
        if resolved_search:
            for t in tasks:
                if t.get("account_id") == account_id and t.get("status") == "active" and (t.get("content_normalized") or "") == resolved_search:
                    candidates.append(t)
            if not candidates:
                # use index
                task_ids = set(r.get("task_id") for r in idx if r.get("account_id") == account_id and r.get("term") == resolved_search)
                if task_ids:
                    for t in tasks:
                        if t.get("account_id") == account_id and t.get("status") == "active" and t.get("id") in task_ids:
                            candidates.append(t)
        if not candidates:
            _record_invocation("todoist_delete_task", account_id, {"account_id": account_id, "search_name": search_name}, "failed", error_message="No matching task", resolved_search_name=resolved_search, duration_ms=int((time.time()-t0)*1000))
            return _err("NOT_FOUND", "No active task matched search_name")
        # deterministic tie-breaker
        def _upd(t):
            return t.get("updated_at") or t.get("created_at") or ""
        candidates.sort(key=_upd, reverse=True)
        target = candidates[0]

    # Transition active|completed -> deleted only
    if target.get("status") == "deleted":
        # idempotent-like: already deleted; but tool requires no success without effect? deletion already applied.
        # Treat as succeeded but no-op is acceptable; still log succeeded.
        inv = _record_invocation("todoist_delete_task", account_id, {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id}, "succeeded", response_payload={"already_deleted": True}, matched_task_id=target.get("id"), resolved_search_name=resolved_search, idempotency_key_val=idempotency_key, duration_ms=int((time.time()-t0)*1000))
        return {"deleted": True, "task_id": target.get("id"), "already_deleted": True, "invocation_id": inv.get("id")}

    if target.get("status") not in ("active", "completed"):
        _record_invocation("todoist_delete_task", account_id, {"account_id": account_id, "task_id": target.get("id")}, "failed", error_message="Invalid transition", matched_task_id=target.get("id"), resolved_search_name=resolved_search, duration_ms=int((time.time()-t0)*1000))
        return _err("INVALID_TRANSITION", "Task cannot be deleted from its current status")

    # Apply deletion
    target["status"] = "deleted"
    target["deleted_at"] = now
    target["updated_at"] = now
    target["last_synced_at"] = now

    # Persist tasks
    updated = False
    for i, t in enumerate(tasks):
        if t.get("id") == target.get("id") and t.get("account_id") == account_id:
            tasks[i] = target
            updated = True
            break
    if not updated:
        _record_invocation("todoist_delete_task", account_id, {"account_id": account_id, "task_id": target.get("id")}, "failed", error_message="Task not found during update", duration_ms=int((time.time()-t0)*1000))
        return _err("NOT_FOUND", "Task not found")
    _save("tasks.json", tasks)

    # Cascade delete search index rows for this task
    idx2 = [r for r in idx if not (r.get("account_id") == account_id and r.get("task_id") == target.get("id"))]
    _save("task_search_index.json", idx2)

    # Update account verification
    acct["last_verified_at"] = now
    acct["updated_at"] = now
    for i, a in enumerate(accounts):
        if a.get("id") == account_id:
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    inv = _record_invocation(
        "todoist_delete_task",
        account_id,
        {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id},
        "succeeded",
        response_payload={"deleted": True, "task_id": target.get("id")},
        matched_task_id=target.get("id"),
        resolved_search_name=resolved_search,
        idempotency_key_val=idempotency_key,
        duration_ms=int((time.time() - t0) * 1000)
    )
    return {"deleted": True, "task_id": target.get("id"), "invocation_id": inv.get("id")}

def todoist_complete_task(account_id, idempotency_key=None, search_name=None, task_id=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _duration_ms():
        return int((time.time() - _t0) * 1000)

    def _new_id(prefix):
        ts = int(time.time() * 1000)
        rnd = os.urandom(10)
        raw = ts.to_bytes(6, "big") + rnd
        enc = base64.b32encode(raw).decode("ascii").rstrip("=").upper()
        return f"{prefix}_{enc}"

    def _normalize(s):
        return " ".join((s or "").strip().lower().split())

    def _append_invocation(inv_rows, acct_id, status, request_payload, resolved_search_name=None, matched_task_id=None, error_message=None, response_payload=None, idem_key=None):
        now = _now()
        inv = {
            "id": _new_id("tdst_inv"),
            "account_id": acct_id,
            "tool_name": "todoist_complete_task",
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "resolved_search_name": resolved_search_name,
            "matched_task_id": matched_task_id,
            "status": status,
            "error_message": error_message,
            "response_payload": response_payload,
            "idempotency_key": idem_key,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        inv_rows.append(inv)
        return inv

    def _finalize_invocation(inv, status, error_message=None, response_payload=None):
        inv["status"] = status
        inv["error_message"] = error_message
        inv["response_payload"] = response_payload
        inv["duration_ms"] = _duration_ms()
        inv["updated_at"] = _now()

    # ---- Validate inputs ----
    if not isinstance(account_id, str) or not re.match(r"^tdst_acct_[0-9A-Z]{10,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id must be a string matching ^tdst_acct_[0-9A-Z]{10,}$")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string")
    if search_name is not None and not isinstance(search_name, str):
        return _err("VALIDATION_ERROR", "search_name must be a string")
    if task_id is not None:
        if not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{10,}$", task_id):
            return _err("VALIDATION_ERROR", "task_id must be a string matching ^tdst_tsk_[0-9A-Z]{10,}$")
    if task_id is None and (search_name is None or _normalize(search_name) == ""):
        return _err("VALIDATION_ERROR", "Either task_id or a non-empty search_name is required")

    # ---- Load store ----
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        accounts = accounts.get("data") or accounts.get("items") or []
    if not isinstance(accounts, list):
        accounts = []

    tasks = _load("tasks.json")
    if isinstance(tasks, dict) and "rows" in tasks:
        tasks = tasks.get("data") or tasks.get("items") or []
    if not isinstance(tasks, list):
        tasks = []

    tsi = _load("task_search_index.json")
    if isinstance(tsi, dict) and "rows" in tsi:
        tsi = tsi.get("data") or tsi.get("items") or []
    if not isinstance(tsi, list):
        tsi = []

    inv_rows = _load("tool_invocations.json")
    if isinstance(inv_rows, dict) and "rows" in inv_rows:
        inv_rows = inv_rows.get("data") or inv_rows.get("items") or []
    if not isinstance(inv_rows, list):
        inv_rows = []

    # ---- Resolve account context (must be active) ----
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if not acct:
        inv = _append_invocation(
            inv_rows,
            account_id,
            "failed",
            {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id},
            resolved_search_name=_normalize(search_name) if search_name is not None else None,
            matched_task_id=None,
            error_message="Account not found",
            response_payload=None,
            idem_key=idempotency_key,
        )
        _finalize_invocation(inv, "failed", error_message="Account not found")
        _save("tool_invocations.json", inv_rows)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("provider") != "todoist":
        inv = _append_invocation(
            inv_rows,
            account_id,
            "failed",
            {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id},
            resolved_search_name=_normalize(search_name) if search_name is not None else None,
            error_message="Unsupported provider for account",
            idem_key=idempotency_key,
        )
        _finalize_invocation(inv, "failed", error_message="Unsupported provider for account")
        _save("tool_invocations.json", inv_rows)
        return _err("VALIDATION_ERROR", "Account provider must be 'todoist'")
    if acct.get("status") != "active":
        inv = _append_invocation(
            inv_rows,
            account_id,
            "failed",
            {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id},
            resolved_search_name=_normalize(search_name) if search_name is not None else None,
            error_message="Account is not active",
            idem_key=idempotency_key,
        )
        _finalize_invocation(inv, "failed", error_message="Account is not active")
        _save("tool_invocations.json", inv_rows)
        return _err("UNAUTHORIZED", "Account is not active")

    # ---- Idempotency (unique(account_id, idempotency_key)) ----
    if idempotency_key:
        for inv in inv_rows:
            if (
                isinstance(inv, dict)
                and inv.get("account_id") == account_id
                and inv.get("idempotency_key") == idempotency_key
            ):
                # Realistic behavior: if we already succeeded, return the previously stored response.
                if inv.get("status") == "succeeded":
                    resp = inv.get("response_payload")
                    if isinstance(resp, dict):
                        return resp
                    # If stored response is missing, fall back to current task snapshot if possible.
                    mid = inv.get("matched_task_id")
                    if mid:
                        trow = next((t for t in tasks if isinstance(t, dict) and t.get("id") == mid), None)
                        if trow:
                            return {"task": trow}
                    return {"task": None}
                # If previous invocation failed, do not silently succeed; proceed with a new attempt.

    resolved_search = _normalize(search_name) if search_name is not None else None

    # ---- Create invocation row upfront ("received" -> "running" -> final) ----
    inv = _append_invocation(
        inv_rows,
        account_id,
        "received",
        {"account_id": account_id, "idempotency_key": idempotency_key, "search_name": search_name, "task_id": task_id},
        resolved_search_name=resolved_search,
        matched_task_id=None,
        error_message=None,
        response_payload=None,
        idem_key=idempotency_key,
    )
    inv["status"] = "running"
    inv["updated_at"] = _now()
    _save("tool_invocations.json", inv_rows)

    # ---- Resolve task ----
    matched = None

    if task_id is not None:
        t = next((t for t in tasks if isinstance(t, dict) and t.get("id") == task_id), None)
        if not t:
            _finalize_invocation(inv, "failed", error_message=f"Task not found: {task_id}")
            _save("tool_invocations.json", inv_rows)
            return _err("NOT_FOUND", f"Task not found: {task_id}")
        # Enforce account scoping (this is a real rule)
        if t.get("account_id") != account_id:
            # This should be forbidden, but must not be mis-triggered by bad auth; we already validated account context.
            _finalize_invocation(inv, "failed", error_message="Rejected: task belongs to a different account")
            inv["matched_task_id"] = t.get("id")
            _save("tool_invocations.json", inv_rows)
            return _err("UNAUTHORIZED", "Rejected: task belongs to a different account")
        matched = t
    else:
        # Search by normalized name using tasks.content_normalized and task_search_index terms
        if resolved_search is None or resolved_search == "":
            _finalize_invocation(inv, "failed", error_message="Either task_id or a non-empty search_name is required")
            _save("tool_invocations.json", inv_rows)
            return _err("VALIDATION_ERROR", "Either task_id or a non-empty search_name is required")

        candidates = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("account_id") != account_id:
                continue
            if t.get("status") != "active":
                continue
            if _normalize(t.get("content_normalized") or "") == resolved_search:
                candidates.append(t)

        # Also consult index for completeness (term match)
        if not candidates:
            indexed_task_ids = set()
            for r in tsi:
                if not isinstance(r, dict):
                    continue
                if r.get("account_id") != account_id:
                    continue
                if (r.get("term") or "") == resolved_search:
                    indexed_task_ids.add(r.get("task_id"))
            if indexed_task_ids:
                for t in tasks:
                    if not isinstance(t, dict):
                        continue
                    if t.get("account_id") != account_id:
                        continue
                    if t.get("status") != "active":
                        continue
                    if t.get("id") in indexed_task_ids:
                        candidates.append(t)

        if not candidates:
            _finalize_invocation(inv, "failed", error_message=f'No matching active task for name "{search_name}"')
            _save("tool_invocations.json", inv_rows)
            return _err("NOT_FOUND", f'No matching active task for name "{search_name}"')

        # Deterministic tie-breaker: most recently updated active task
        def _ts(v):
            if not isinstance(v, str) or not v:
                return ""
            return v

        candidates.sort(key=lambda x: (_ts(x.get("updated_at")), _ts(x.get("created_at")), x.get("id") or ""), reverse=True)
        matched = candidates[0]

    # ---- Enforce lifecycle transition and apply ----
    status = matched.get("status")
    if status != "active":
        # complete only active -> completed; don't modify deleted tasks
        if status == "completed":
            _finalize_invocation(inv, "failed", error_message="Rejected: task is already completed")
            inv["matched_task_id"] = matched.get("id")
            _save("tool_invocations.json", inv_rows)
            return _err("INVALID_TRANSITION", "Rejected: task is already completed")
        if status == "deleted":
            _finalize_invocation(inv, "failed", error_message="Rejected: cannot complete a deleted task")
            inv["matched_task_id"] = matched.get("id")
            _save("tool_invocations.json", inv_rows)
            return _err("INVALID_TRANSITION", "Rejected: cannot complete a deleted task")
        _finalize_invocation(inv, "failed", error_message=f"Rejected: cannot complete task from status '{status}'")
        inv["matched_task_id"] = matched.get("id")
        _save("tool_invocations.json", inv_rows)
        return _err("INVALID_TRANSITION", f"Rejected: cannot complete task from status '{status}'")

    now = _now()
    matched["status"] = "completed"
    matched["completed_at"] = now
    matched["updated_at"] = now
    # application-enforced invariant: deleted_at must be null when not deleted
    if matched.get("deleted_at") is not None and matched.get("status") != "deleted":
        matched["deleted_at"] = None

    # Ensure search index invariant: exactly one full term row exists with term=content_normalized
    content_norm = matched.get("content_normalized") or _normalize(matched.get("content") or "")
    matched["content_normalized"] = content_norm

    # Remove any existing "full" rows for this task/account, then add one correct row.
    tsi = [r for r in tsi if not (isinstance(r, dict) and r.get("account_id") == account_id and r.get("task_id") == matched.get("id") and r.get("term_type") == "full")]
    tsi.append(
        {
            "id": _new_id("tdst_tsi"),
            "account_id": account_id,
            "task_id": matched.get("id"),
            "term": content_norm,
            "term_type": "full",
            "created_at": now,
            "updated_at": now,
        }
    )

    # ---- Persist ----
    _save("tasks.json", tasks)
    _save("task_search_index.json", tsi)

    inv["matched_task_id"] = matched.get("id")
    response = {"task": matched}
    _finalize_invocation(inv, "succeeded", response_payload=response)
    _save("tool_invocations.json", inv_rows)

    return response

def todoist_get_task(account_id, task_id, **_extra):
    import json, os, datetime, time, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _duration_ms():
        return int((time.time() - _t0) * 1000)

    def _new_id(prefix):
        import base64
        ts = int(time.time() * 1000)
        rnd = os.urandom(10)
        raw = ts.to_bytes(6, "big") + rnd
        enc = base64.b32encode(raw).decode("ascii").rstrip("=").upper()
        return f"{prefix}_{enc}"

    def _select_account(accounts, acct_id):
        for a in accounts:
            if a.get("id") == acct_id:
                return a
        return None

    # Validation
    if not isinstance(account_id, str) or not re.match(r"^tdst_acct_[0-9A-Z]{10,}$", account_id or ""):
        return _err("VALIDATION_ERROR", "account_id must be a string matching ^tdst_acct_[0-9A-Z]{10,}$")
    if not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{10,}$", task_id or ""):
        return _err("VALIDATION_ERROR", "task_id must be a string matching ^tdst_tsk_[0-9A-Z]{10,}$")

    accounts = _load("accounts.json")
    tasks = _load("tasks.json")
    invs = _load("tool_invocations.json")

    acct = _select_account(accounts, account_id)
    if not acct:
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        # Log failed invocation (note: tool_name enum does not include todoist_get_task; cannot log to tool_invocations safely)
        return _err("UNAUTHORIZED", "Account is not active")

    t = None
    for row in tasks:
        if row.get("id") == task_id:
            t = row
            break
    if not t:
        return _err("NOT_FOUND", "Task not found")
    if t.get("account_id") != account_id:
        return _err("UNAUTHORIZED", "Task does not belong to this account")

    # Staleness policy: if last_synced_at missing or older than 10 minutes, refresh mirror timestamp.
    # No real Todoist call offline; treat as successful refresh and update last_verified_at.
    now = _now()
    stale = False
    last_synced = t.get("last_synced_at")
    if not isinstance(last_synced, str) or not last_synced.endswith("Z"):
        stale = True
    else:
        try:
            dt = datetime.datetime.fromisoformat(last_synced.replace("Z", "+00:00"))
            if (datetime.datetime.now(datetime.timezone.utc) - dt).total_seconds() > 600:
                stale = True
        except Exception:
            stale = True

    if stale:
        t["last_synced_at"] = now
        t["updated_at"] = now
        acct["last_verified_at"] = now
        acct["updated_at"] = now
        _save("tasks.json", tasks)
        _save("accounts.json", accounts)

    return {"task": {k: v for k, v in t.items()}}

def todoist_get_projects(account_id, status=None, name_query=None, is_inbox=None, is_archived=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _cursor_decode(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            n = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            v = int(n)
            return max(0, v)
        except Exception:
            return None

    def _cursor_encode(i):
        return base64.urlsafe_b64encode(str(int(i)).encode("utf-8")).decode("ascii").rstrip("=")

    def _select_account(accounts, acct_id):
        for a in accounts:
            if a.get("id") == acct_id:
                return a
        return None

    # Validation
    if not isinstance(account_id, str) or not re.match(r"^tdst_acct_[0-9A-Z]{10,}$", account_id or ""):
        return _err("VALIDATION_ERROR", "account_id must be a string matching ^tdst_acct_[0-9A-Z]{10,}$")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted")
    if name_query is not None and not isinstance(name_query, str):
        return _err("VALIDATION_ERROR", "name_query must be a string")
    if is_inbox is not None and not isinstance(is_inbox, bool):
        return _err("VALIDATION_ERROR", "is_inbox must be a boolean")
    if is_archived is not None and not isinstance(is_archived, bool):
        return _err("VALIDATION_ERROR", "is_archived must be a boolean")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "name"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, name")

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    offset = _cursor_decode(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "Invalid cursor")

    accounts = _load("accounts.json")
    projects = _load("projects.json")

    acct = _select_account(accounts, account_id)
    if not acct:
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        return _err("UNAUTHORIZED", "Account is not active")

    rows = []
    nq = (name_query or "").strip().lower()
    for p in projects:
        if p.get("account_id") != account_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        if is_inbox is not None:
            if bool(p.get("is_inbox")) != is_inbox:
                continue
        if is_archived is not None:
            if bool(p.get("is_archived")) != is_archived:
                continue
        if nq:
            if nq not in (p.get("name") or "").strip().lower():
                continue
        rows.append(p)

    reverse = (sort_order == "desc")
    if sort_by == "name":
        rows.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("id") or ""), reverse=reverse)
    else:
        rows.sort(key=lambda x: (x.get(sort_by) or "", x.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _cursor_encode(next_off) if has_more else None

    return {
        "projects": [dict(r) for r in page],
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

def todoist_get_accounts(provider=None, status=None, todoist_user_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0149000" if __import__("os").path.isdir("./environment_mix/0149000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _cursor_decode(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            n = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            v = int(n)
            return max(0, v)
        except Exception:
            return None

    def _cursor_encode(i):
        return base64.urlsafe_b64encode(str(int(i)).encode("utf-8")).decode("ascii").rstrip("=")

    # Validation
    if provider is not None:
        if not isinstance(provider, str) or provider not in ("todoist",):
            return _err("VALIDATION_ERROR", "provider must be: todoist")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "revoked", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked, error")
    if todoist_user_id is not None and not isinstance(todoist_user_id, str):
        return _err("VALIDATION_ERROR", "todoist_user_id must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "last_verified_at"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, last_verified_at")
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    offset = _cursor_decode(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "Invalid cursor")

    accounts = _load("accounts.json")

    rows = []
    for a in accounts:
        if provider is not None and a.get("provider") != provider:
            continue
        if status is not None and a.get("status") != status:
            continue
        if todoist_user_id is not None and a.get("todoist_user_id") != todoist_user_id:
            continue
        # never return access_token_ciphertext
        out = {k: v for k, v in a.items() if k != "access_token_ciphertext"}
        rows.append(out)

    reverse = (sort_order == "desc")
    rows.sort(key=lambda x: (x.get(sort_by) or "", x.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _cursor_encode(next_off) if has_more else None

    return {
        "accounts": [dict(r) for r in page],
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
